# Surah Al-Baqarah (chapter 2) — part 20: ayat 191-200 (IDs 198-207)
SURAH = 2

ENTRIES = {
198: (
"اور انہیں جہاں پاؤ قتل کرو اور انہیں اس جگہ سے نکال دو جہاں سے انہوں نے تمہیں نکالا — اور فتنہ (شر/فساد) قتل سے بڑھ کر ہے — اور ان سے جنگ نہ کرو مسجد حرام کے پاس جب تک وہ تم سے لڑیں اس (مسجد) میں — پھر اگر وہ تم سے لڑیں تو انہیں قتل کرو — یہی سزا ہے کافروں کی۔",
"""۱۔ جنگ کے احکام بیان ہو رہے ہیں — دفاع، حدود اور مقامات کی حرمت۔
۲۔ ’’وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ‘‘ — اور انہیں جہاں پاؤ قتل کرو — یعنی میدانِ جنگ میں مقابلے والے کو روکو۔
۳۔ ’’وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ‘‘ — اور انہیں اس جگہ سے نکال دو جہاں سے انہوں نے تمہیں نکالا — یعنی مکہ سے ان کی طرف کا اخراج جائز جواب ہے۔
۴۔ ’’وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ‘‘ — اور فتنہ (شر/فساد) قتل سے بڑھ کر ہے — یعنی دین کو مٹانے اور ظلم کی کوشش قتل سے بھی سنگین جرم ہے۔
۵۔ ’’وَلَا تُقَاتِلُوهُمْ عِندَ الْمَسْجِدِ الْحَرَامِ حَتَّىٰ يُقَاتِلُوكُمْ فِيهِ‘‘ — اور ان سے جنگ نہ کرو مسجد حرام کے پاس جب تک وہ تم سے لڑیں اس (مسجد) میں — یعنی مسجد حرام میں جنگ حتیٰ کہ دفاعی طور پر تب ہی ہوگی جب مخالف وہاں لڑائی شروع کرے۔
۶۔ ’’فَإِن قَاتَلُوكُمْ فَاقْتُلُوهُمْ‘‘ — پھر اگر وہ تم سے لڑیں تو انہیں قتل کرو — یعنی دفاع کامل حق ہے۔
۷۔ ’’كَذَٰلِكَ جَزَاءُ الْكَافِرِينَ‘‘ — یہی سزا ہے کافروں کی۔
۸۔ عملی سبق: دفاع خود ضروری مگر مقاماتِ مقدسہ کی حرمت محفوظ رہے — سب سے بڑی فتنہ دشمنیِ دین ہے۔"""
),
199: (
"پھر اگر وہ باز آ جائیں تو بے شک اللہ بخشنے والا، نہایت رحم والا ہے۔",
"""۱۔ جنگ کے دوران اگر دشمن باز آ جائے تو درگزر کا حکم۔
۲۔ ’’فَإِنِ انتَهَوْا فَإِنَّ اللّٰہَ غَفُورٌ رَّحِيمٌ‘‘ — پھر اگر وہ باز آ جائیں تو بے شک اللہ بخشنے والا، نہایت رحم والا ہے — یعنی اگر مخالفین توبہ کریں اور لڑائی چھوڑ دیں تو پیچھا چھوڑ دینا لازم ہے۔
۳۔ اس آیت میں یہ اصول ہے کہ اسلام لڑائی میں حد سے بڑھنا نہیں چاہتا — جنگ دفاع ہے، انتقام نہیں۔
۴۔ عملی سبق: صلح کی پیشکش قبول کرو؛ دشمن کے باز آنے پر درگزر کرو — اللہ کی رحمت غالب ہے۔"""
),
200: (
"اور ان سے جنگ کرو یہاں تک کہ فتنہ (شر/فساد) نہ رہے اور (حکمرانی) دین اللہ کے لیے ہو — پھر اگر وہ باز آ جائیں تو ظالموں کے سوا (کسی پر) کوئی زیادتی نہیں۔",
"""۱۔ لڑائی کا آخری مقصد — فتنہ اور ظلم کا خاتمہ، اللہ کے دین کا قیام۔
۲۔ ’’وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَۃٌ‘‘ — اور ان سے جنگ کرو یہاں تک کہ فتنہ (شر/فساد) نہ رہے — یعنی ظلم، فساد اور دشمنیِ دین ختم ہو۔
۳۔ ’’وَيَكُونَ الدِّينُ لِلّٰہِ‘‘ — اور (حکمرانی) دین اللہ کے لیے ہو — یعنی اللہ کا نظام قانون نافذ ہو۔
۴۔ ’’فَإِنِ انتَهَوْا فَلَا عُدْوَانَ إِلَّا عَلَى الظَّالِمِينَ‘‘ — پھر اگر وہ باز آ جائیں تو ظالموں کے سوا (کسی پر) کوئی زیادتی نہیں — یعنی اگر مخالفین چھوڑ دیں تو ان پر کارروائی ممنوع ہے؛ زیادتی صرف ظالموں پر جائز ہے۔
۵۔ عملی سبق: جنگ کبھی بھی اپنی طبیعت نہیں؛ مقصد ظلم کا خاتمہ ہے — صلح ہو جائے تو فوراً نفرت چھوڑ دیں۔"""
),
201: (
"(بڑی) ماہ مقدس (ماہ حرام) کے بدلے (بڑی) ماہ مقدس — اور حرمتیں (بدلے) بدلہ ہیں — پس جو کوئی تم پر زیادتی کرے تو اس پر ویسی ہی زیادتی کرو جیسی اس نے تم پر کی — اور اللہ سے ڈرو — اور جان لو کہ اللہ متقیوں کے ساتھ ہے۔",
"""۱۔ حرمتوں کا بدلہ — لڑائی اور مقامات و مہینے کی حرمت کے احکام۔
۲۔ ’’الشَّهْرُ الْحَرَامُ بِالشَّهْرِ الْحَرَامِ وَالْحُرُمَاتُ قِصَاصٌ‘‘ — (بڑی) ماہ مقدس (ماہ حرام) کے بدلے (بڑی) ماہ مقدس — اور حرمتیں (بدلے) بدلہ ہیں — یعنی حرمت والے مہینوں میں لڑائی کا بدلہ بھی حرمت والے مہینوں میں ہے؛ زیادتی کا بدلہ زیادتی کے برابر۔
۳۔ ’’فَمَنِ اعْتَدَىٰ عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدَىٰ عَلَيْكُمْ‘‘ — پس جو کوئی تم پر زیادتی کرے تو اس پر ویسی ہی زیادتی کرو جیسی اس نے تم پر کی — یعنی برابر کی کارروائی جائز ہے۔
۴۔ ’’وَاتَّقُوا اللّٰہَ وَاعْلَمُوا أَنَّ اللّٰہَ مَعَ الْمُتَّقِينَ‘‘ — اور اللہ سے ڈرو — اور جان لو کہ اللہ متقیوں کے ساتھ ہے — یعنی حد سے نہ بڑھیں؛ اللہ متقیوں کا ساتھی ہے۔
۵۔ عملی سبق: بدلہ لو تو حد میں رہو؛ زیادہ تر تقویٰ اختیار کرو — اللہ کی مدد متقیوں کے ساتھ ہے۔"""
),
202: (
"اور اللہ کی راہ میں خرچ کرو اور اپنے ہاتھ (تباہی) کے حوالے نہ کرو — اور نیکی کرو — بے شک اللہ نیکی کرنے والوں کو پسند کرتا ہے۔",
"""۱۔ اللہ کی راہ میں مال خرچ کرنے کا حکم — اور تباہی سے بچنے کی ہدایت۔
۲۔ ’’وَأَنفِقُوا فِي سَبِيلِ اللّٰہِ‘‘ — اور اللہ کی راہ میں خرچ کرو — یعنی جہاد اور حاجت مندوں پر مال خرچ کرنا اللہ کی راہ کا کام ہے۔
۳۔ ’’وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَۃِ‘‘ — اور اپنے ہاتھ (تباہی) کے حوالے نہ کرو — یعنی اپنی جان کو خطرے میں مت ڈالو؛ خودکشی اور بلا ضرورت خطرہ مولانا ممنوع ہے۔
۴۔ ’’وَأَحْسِنُوا إِنَّ اللّٰہَ يُحِبُّ الْمُحْسِنِينَ‘‘ — اور نیکی کرو — بے شک اللہ نیکی کرنے والوں کو پسند کرتا ہے۔
۵۔ عملی سبق: خیر کے کاموں میں مال خرچ کرو مگر اپنی حفاظت بھی ضروری خیال کرو؛ اللہ نیک لوگوں سے محبت کرتا ہے۔"""
),
203: (
"اور حج اور عمرہ کو اللہ کے لیے پورا کرو — پھر اگر تم روک دیے جاؤ (دشمن یا حالات سے) تو آنے والا ہدیہ (قربان گاہ تک) پہنچا دو — اور اپنے سر نہ مونڈو یہاں تک کہ ہدیہ اپنی جگہ پہنچ جائے — پھر جو کوئی تم میں سے بیمار ہو یا اس کے سر میں تکلیف ہو تو فدیہ (عوض) روزہ رکھنا ہے یا صدقہ دینا یا قربانی کرنا — پھر جب تم محفوظ ہو جاؤ تو جو کوئی عمرہ سے (پہلے) حج سے فائدہ (تمتع) اٹھائے تو اس پر آنے والا ہدیہ (قربان کرنا) ضروری ہے — اور جو نہ پائے تو (اس پر) روزے تین حج میں اور سات گھر واپسی پر — یہ پورے دس ہیں — یہ اس کے لیے ہے جس کا گھر مسجد حرام کے پاس نہ ہو — اور اللہ سے ڈرو اور جان لو کہ اللہ سخت عذاب والا ہے۔",
"""۱۔ حج اور عمرہ کے بنیادی احکام بیان ہو رہے ہیں — تمتع اور فدیہ۔
۲۔ ’’وَأَتِمُّوا الْحَجَّ وَالْعُمْرَۃَ لِلّٰہِ‘‘ — حج اور عمرہ کو اللہ کے لیے پورا کرو — یعنی کامل طور پر عمل کرو۔
۳۔ ’’فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ‘‘ — پھر اگر تم روک دیے جاؤ (دشمن یا حالات سے) تو آنے والا ہدیہ (قربان گاہ تک) پہنچا دو — یعنی اگر کوئی رکاوٹ آئے تو قربا ن کے جانور بھیج دیں۔
۴۔ ’’وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ الْهَدْيُ مَحِلَّهُ‘‘ — اور اپنے سر نہ مونڈو یہاں تک کہ ہدیہ اپنی جگہ پہنچ جائے — یعنی قربانی ہونے سے پہلے حلق نہ کریں۔
۵۔ ’’فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِ أَذًى مِّن رَّأْسِهِ فَفِدْيَۃٌ مِّن صِيَامٍ أَوْ صَدَقَۃٍ أَوْ نُسُكٍ‘‘ — پھر جو کوئی تم میں سے بیمار ہو یا اس کے سر میں تکلیف ہو تو فدیہ (عوض) روزہ رکھنا ہے یا صدقہ دینا یا قربانی کرنا — یعنی سر مونڈنے کی صورت میں تینوں میں اختیار۔
۶۔ ’’فَإِذَا أَمِنتُمْ فَمَن تَمَتَّعَ بِالْعُمْرَۃِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ‘‘ — پھر جب تم محفوظ ہو جاؤ تو جو کوئی عمرہ سے (پہلے) حج سے فائدہ (تمتع) اٹھائے تو اس پر آنے والا ہدیہ (قربان کرنا) ضروری ہے — یعنی تمتع والے حج میں قربانی واجب ہے۔
۷۔ ’’فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَاثَۃِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَۃٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَۃٌ كَامِلَۃٌ‘‘ — اور جو نہ پائے تو (اس پر) روزے تین حج میں اور سات گھر واپسی پر — یہ پورے دس ہیں۔
۸۔ ’’ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ‘‘ — یہ اس کے لیے ہے جس کا گھر مسجد حرام کے پاس نہ ہو — یعنی مکہ کے رہنے والوں پر تمتع کا حکم نہیں۔
۹۔ ’’وَاتَّقُوا اللّٰہَ وَاعْلَمُوا أَنَّ اللّٰہَ شَدِيدُ الْعِقَابِ‘‘ — اور اللہ سے ڈرو اور جان لو کہ اللہ سخت عذاب والا ہے۔
۱۰۔ عملی سبق: حج کے احکام صحیح طور پر سیکھ کر عمل کرو؛ غلط عمل سے اجتناب؛ اللہ کے احکامات کی حرمت محفوظ رکھیں۔"""
),
204: (
"حج گنتی کے معلوم مہینوں میں ہے — پس جو کوئی ان مہینوں میں حج فرض کرے تو (حج کے دوران) کوئی بے حیائی نہیں، کوئی نافرمانی نہیں اور کوئی جھگڑا نہیں — اور تم جو بھی بھلائی کرو اللہ اسے جانتا ہے — اور (سفر کا) سامان لو (ساتھ) — بے شک بہترین سامان تقویٰ ہے — اور مجھ سے ڈرو اے عقل والو!۔",
"""۱۔ حج کے مہینے (شوال، ذوالقعدہ، عشرہ ذی الحجہ) اور حج کے آداب بیان ہو رہے ہیں۔
۲۔ ’’الْحَجُّ أَشْهُرٌ مَّعْلُومَاتٌ‘‘ — حج گنتی کے معلوم مہینوں میں ہے — یعنی حج کا عمل مخصوص مہینوں میں ادا کیا جاتا ہے۔
۳۔ ’’فَمَن فَرَضَ فِيهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ‘‘ — پس جو کوئی ان مہینوں میں حج فرض کرے تو (حج کے دوران) کوئی بے حیائی نہیں، کوئی نافرمانی نہیں اور کوئی جھگڑا نہیں — یعنی حج کے دوران شہوت، گناہ اور جھگڑا ممنوع ہیں۔
۴۔ ’’وَمَا تَفْعَلُوا مِنْ خَيْرٍ يَعْلَمْهُ اللّٰہُ‘‘ — اور تم جو بھی بھلائی کرو اللہ اسے جانتا ہے — یعنی حج کی ہر نیکی اللہ کے علم میں ہے۔
۵۔ ’’وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَىٰ‘‘ — اور (سفر کا) سامان لو (ساتھ) — بے شک بہترین سامان تقویٰ ہے — یعنی سفر کا زادِ راہ تقویٰ سب سے بہترین ہے۔
۶۔ ’’وَاتَّقُونِ يَا أُولِي الْأَلْبَابِ‘‘ — اور مجھ سے ڈرو اے عقل والو!۔
۷۔ عملی سبق: حج کی سفر میں اپنی ذات کی ذمہ داری نبھائیں؛ تقویٰ کو اپنی زندگی میں زادِ راہ بنائیں۔"""
),
205: (
"تمہارے اوپر کوئی گناہ نہیں کہ تم اپنے رب کا فضل (حصہ) تلاش کرو (تجارت سے) — پھر جب تم عرفات سے (نکل کر) لوٹو تو یاد کرو اللہ کو مشعر الحرام پر — اور یاد کرو اسے جیسے اس نے تمہیں ہدایت دی — اگرچہ پہلے تم گمراہوں میں سے تھے۔",
"""۱۔ حج میں تجارت کی اجازت — لیکن اس کے اصول بیان ہو رہے ہیں۔
۲۔ ’’لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا فَضْلًا مِّن رَّبِّكُمْ‘‘ — تمہارے اوپر کوئی گناہ نہیں کہ تم اپنے رب کا فضل (حصہ) تلاش کرو — یعنی حج کے سفر میں تجارت جائز ہے۔
۳۔ ’’فَإِذَا أَفَضْتُم مِّنْ عَرَفَاتٍ فَاذْكُرُوا اللّٰہَ عِندَ الْمَشْعَرِ الْحَرَامِ‘‘ — پھر جب تم عرفات سے (نکل کر) لوٹو تو یاد کرو اللہ کو مشعر الحرام پر — یعنی عرفات سے واپسی رات کو مزدلفہ (مشعر الحرام) میں اللہ کا ذکر کرو۔
۴۔ ’’وَاذْكُرُوهُ كَمَا هَدَاكُمْ وَإِن كُنتُم مِّن قَبْلِهِ لَمِنَ الضَّالِّينَ‘‘ — اور یاد کرو اسے جیسے اس نے تمہیں ہدایت دی — اگرچہ پہلے تم گمراہوں میں سے تھے — یعنی اللہ کی ہدایت ہر مسلمان کے لیے عظیم نعمت ہے۔
۵۔ عملی سبق: حج میں تجارت اور عبادت دونوں ممکن ہیں؛ دونوں کے اصولوں کا توازن رکھیں۔"""
),
206: (
"پھر افاضہ کرو جہاں سے لوگ افاضہ کرتے ہیں — اور اللہ سے مغفرت مانگو — بے شک اللہ بخشنے والا، نہایت رحم والا ہے۔",
"""۱۔ حجاج کو مزدلفہ سے واپسی کا طریقہ بتایا جا رہا ہے۔
۲۔ ’’ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ‘‘ — پھر افاضہ کرو جہاں سے لوگ افاضہ کرتے ہیں — یعنی مزدلفہ سے منیٰ کی طرف واپسی (اسی طرح جیسے عام لوگ کرتے ہیں)۔
۳۔ ’’وَاسْتَغْفِرُوا اللّٰہَ إِنَّ اللّٰہَ غَفُورٌ رَّحِيمٌ‘‘ — اور اللہ سے مغفرت مانگو — بے شک اللہ بخشنے والا، نہایت رحم والا ہے — یعنی ہر لمحہ اللہ سے مغفرت مانگتے رہو۔
۴۔ عملی سبق: حج کے سفر میں خود کو عاجز رکھیں؛ اللہ کی مغفرت مانگنے کی عادت ڈالیں۔"""
),
207: (
"پھر جب تم اپنے حج کے اعمال مکمل کر لو تو یاد کرو اللہ کو — جیسا کہ اپنے باپ دادا کو یاد کرتے تھے یا اس سے بھی زیادہ یاد کرو — پس لوگوں میں سے کچھ وہ ہیں جو کہتے ہیں: اے ہمارے رب! ہمیں دنیا میں (نعمتیں) دے — اور اس کے لیے آخرت میں کوئی حصہ نہیں۔",
"""۱۔ حج کے بعد دعا اور ذکر — دنیا اور آخرت کی دعا کے دو مختلف نمونے۔
۲۔ ’’فَاذْكُرُوا اللّٰہَ كَذِكْرِكُمْ آبَاءَكُمْ أَوْ أَشَدَّ ذِكْرًا‘‘ — یاد کرو اللہ کو — جیسا کہ اپنے باپ دادا کو یاد کرتے تھے یا اس سے بھی زیادہ یاد کرو — یعنی اللہ کی محبت اور ذکر آبائی رشتوں سے بڑھ کر ہویا۔
۳۔ ’’فَمِنَ النَّاسِ مَن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا وَمَا لَهُ فِي الْآخِرَۃِ مِنْ خَلَاقٍ‘‘ — پس لوگوں میں سے کچھ وہ ہیں جو کہتے ہیں: اے ہمارے رب! ہمیں دنیا میں (نعمتیں) دے — اور اس کے لیے آخرت میں کوئی حصہ نہیں — یعنی خالص دنیاوی انسان۔
۴۔ اس دعا میں لوگوں کی ایک قسم کا بیان ہے — جو صرف دنیا چاہتے ہیں اور آخرت میں ان کا کوئی حصہ نہیں۔
۵۔ یاد رکھیں — خالص دنیاوی دعا بذاتِ خود گناہ نہیں مگر آخرت سے غفلت نقصان ہے۔
۶۔ عملی سبق: دنیا کی دعا کے ساتھ آخرت کی فکر بھی رکھیں — دعا کا اصل توازن اسی میں ہے۔"""
),
}
